public with sharing class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact contactRecord : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
                AND Email != null
            WITH USER_MODE
        ]) {
            Integer separatorIndex = contactRecord.Email.lastIndexOf('@');

            // Ignore malformed addresses that do not have a usable domain.
            if (separatorIndex <= 0 ||
                separatorIndex == contactRecord.Email.length() - 1) {
                continue;
            }

            String domain = contactRecord.Email
                .substring(separatorIndex + 1)
                .toLowerCase();

            if (!contactsByDomain.containsKey(domain)) {
                contactsByDomain.put(domain, new List<Contact>());
            }
            contactsByDomain.get(domain).add(contactRecord);
        }

        return contactsByDomain;
    }
}
