public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field is required.');
            }
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            Schema.SObjectType objectType = resolveObject(objectApiName);
            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();

            if (!objectDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to this object.');
            }
            if (!objectDescribe.isQueryable()) {
                throw new SearchException('This object cannot be queried.');
            }

            // Normalize metadata keys explicitly for case-insensitive lookup.
            Map<String, Schema.SObjectField> fieldMap =
                new Map<String, Schema.SObjectField>();
            Map<String, Schema.SObjectField> describedFields =
                objectDescribe.fields.getMap();

            for (String fieldName : describedFields.keySet()) {
                fieldMap.put(fieldName.toLowerCase(), describedFields.get(fieldName));
            }

            Schema.DescribeFieldResult idField =
                requireReadableField('Id', fieldMap);

            List<String> selectFields = new List<String>{ idField.getName() };
            Set<String> selectedNames =
                new Set<String>{ idField.getName().toLowerCase() };

            for (String requestedField : fields) {
                Schema.DescribeFieldResult fieldDescribe =
                    requireReadableField(requestedField, fieldMap);
                String canonicalName = fieldDescribe.getName();

                // Avoid duplicate SELECT fields, including a requested Id.
                if (selectedNames.add(canonicalName.toLowerCase())) {
                    selectFields.add(canonicalName);
                }
            }

            Map<String, Object> binds = new Map<String, Object>();
            List<String> conditions = new List<String>();

            if (filters != null) {
                Integer bindIndex = 0;
                for (String filterField : filters.keySet()) {
                    Schema.DescribeFieldResult fieldDescribe =
                        requireReadableField(filterField, fieldMap);

                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException(
                            'Field cannot be filtered: ' + fieldDescribe.getName()
                        );
                    }

                    String bindName = 'filterValue' + String.valueOf(bindIndex);
                    bindIndex++;

                    // Preserve the supplied type, including null. Never interpolate values.
                    binds.put(bindName, filters.get(filterField));
                    conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                }
            }

            String sortFieldName;
            if (!String.isBlank(orderByField)) {
                Schema.DescribeFieldResult orderField =
                    requireReadableField(orderByField, fieldMap);

                if (!orderField.isSortable()) {
                    throw new SearchException(
                        'Field cannot be sorted: ' + orderField.getName()
                    );
                }
                sortFieldName = orderField.getName();
            }

            // All interpolated identifiers come exclusively from describe metadata.
            String soql =
                'SELECT ' + String.join(selectFields, ', ') +
                ' FROM ' + objectDescribe.getName();

            if (!conditions.isEmpty()) {
                soql += ' WHERE ' + String.join(conditions, ' AND ');
            }
            if (sortFieldName != null) {
                soql += ' ORDER BY ' + sortFieldName + ' ASC';
            }

            binds.put('rowLimit', maxRows);
            soql += ' LIMIT :rowLimit';

            // User mode enforces CRUD, FLS, sharing, and applicable restriction rules.
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            // Includes invalid value/field type combinations and query access failures.
            throw new SearchException(
                'The search could not be completed with the supplied parameters.'
            );
        }
    }

    private static Schema.SObjectType resolveObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }

        Map<String, Schema.SObjectType> objectTypes = Schema.getGlobalDescribe();
        for (String knownName : objectTypes.keySet()) {
            if (knownName.equalsIgnoreCase(objectApiName)) {
                return objectTypes.get(knownName);
            }
        }

        throw new SearchException('Object does not exist: ' + objectApiName);
    }

    private static Schema.DescribeFieldResult requireReadableField(
        String fieldName,
        Map<String, Schema.SObjectField> fieldMap
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('A field API name cannot be blank.');
        }

        Schema.SObjectField fieldToken = fieldMap.get(fieldName.toLowerCase());
        if (fieldToken == null) {
            throw new SearchException('Field does not exist on this object: ' + fieldName);
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException(
                'You do not have read access to field: ' + fieldDescribe.getName()
            );
        }

        return fieldDescribe;
    }
}
