public with sharing class AccountScoringJob implements Queueable {
    private static final Integer CHUNK_SIZE = 200;
    private static final Integer MAX_ACCOUNTS = 50000;
    private static final Integer MAX_CHAIN_DEPTH = 250;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        if (accountIds != null && accountIds.size() > MAX_ACCOUNTS) {
            throw new IllegalArgumentException(
                'AccountScoringJob supports at most 50,000 account IDs.'
            );
        }

        // Copy the input so subsequent caller changes cannot affect this job.
        this.accountIds = accountIds == null
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        AsyncOptions options = new AsyncOptions();
        // Explicit depth overrides the Developer Edition default and enables
        // testing the complete queueable chain at Test.stopTest().
        options.MaximumQueueableStackDepth = MAX_CHAIN_DEPTH;

        return System.enqueueJob(
            new AccountScoringJob(accountIds),
            options
        );
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        List<Id> currentIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < CHUNK_SIZE) {
                currentIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        List<Account> updates = new List<Account>();

        // One query, enforcing the submitting user's access and field access.
        for (Account source : [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentIds
            WITH USER_MODE
        ]) {
            String rating = 'Cold';

            if (source.AnnualRevenue != null) {
                if (source.AnnualRevenue >= 1000000) {
                    rating = 'Hot';
                } else if (source.AnnualRevenue >= 100000) {
                    rating = 'Warm';
                }
            }

            // Only submit fields this job actually changes.
            updates.add(new Account(
                Id = source.Id,
                Rating = rating
            ));
        }

        // One DML statement, enforcing update access to Account and Rating.
        update as user updates;

        if (!remainingIds.isEmpty()) {
            if (System.isQueueable()) {
                // Children inherit the maximum depth established by the root.
                System.enqueueJob(new AccountScoringJob(remainingIds));
            } else {
                // A direct execute(null) call must establish a configured root
                // for the remaining work rather than use DE's default depth.
                start(remainingIds);
            }
        }
    }
}
