public with sharing class ErpSyncFinalizer implements Finalizer {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null
            ? new Set<Id>()
            : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean succeeded = context.getResult() == System.ParentJobResult.SUCCESS;

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt,
            Status__c = succeeded ? 'Success' : 'Failed'
        );

        if (!succeeded) {
            Exception failure = context.getException();
            String errorMessage = failure == null ? null : failure.getMessage();

            jobLog.Error__c = errorMessage == null
                ? null
                : errorMessage.left(255);
        }

        // Persist the operational log in system mode, independently of account permissions.
        insert jobLog;

        if (!succeeded && attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
