                OpportunitiesSelector.class
            );
            uow = (fflib_ISObjectUnitOfWork) mocks.mock(
                fflib_SObjectUnitOfWork.class
            );

            requestedIds = new Set<Id>();
            for (Opportunity opportunity : selected) {
                requestedIds.add(opportunity.Id);
            }
            // Also request an opportunity that the selector does not return.
            // This keeps the input nonempty even when selected is empty.
            requestedIds.add(
                fflib_IDGenerator.generate(Opportunity.SObjectType)
            );

            mocks.startStubbing();
            mocks.when(selector.getSObjectType())
                .thenReturn(Opportunity.SObjectType);
