public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance(
            new Application.AfterCommitEventDML()
        );

        Date today = Date.today();
        Integer closedCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName == 'Closed Won') {
                continue;
            }

            // Use a sparse update so unrelated selected fields are not written.
            uow.registerDirty(new Opportunity(
                Id = opportunity.Id,
                StageName = 'Closed Won',
                CloseDate = today
            ));

            uow.registerPublishAfterSuccessTransaction(new Deal_Won__e(
                Opportunity_Id__c = String.valueOf(opportunity.Id),
                Amount__c = opportunity.Amount
            ));

            closedCount++;
        }

        if (closedCount == 0) {
            return 0;
        }

        // Do not catch saving exceptions: the UoW rolls back and rethrows.
        uow.commitWork();
        return closedCount;
    }
}
