public with sharing class ContactPhoneCleanup {
    /*
     * Security change: the query and update run in user mode to enforce
     * sharing and CRUD/FLS. The update uses the USER_MODE overload of
     * Database.update, retaining false for partial-success behavior.
     *
     * Null or empty input returns an empty map without querying or updating.
     * Read-access violations throw; the returned map covers per-record
     * update failures.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
                AND Phone != null
            WITH USER_MODE
        ];

        for (Contact contactRecord : contacts) {
            // Apply the requested rule: retain only ASCII digits and '+'.
            contactRecord.Phone = contactRecord.Phone.replaceAll('[^0-9+]', '');
        }

        if (contacts.isEmpty()) {
            return errorsByContactId;
        }

        List<Database.SaveResult> saveResults = Database.update(
            contacts,
            false,
            AccessLevel.USER_MODE
        );

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                // Failed SaveResults may not contain an Id; use the input record.
                errorsByContactId.put(
                    contacts[i].Id,
                    saveResults[i].getErrors()[0].getMessage()
                );
            }
        }

        return errorsByContactId;
    }
}
