public with sharing class PipelineSummary {
    /**
     * Returns inclusive CloseDate totals for the four managed stages.
     *
     * A single grouped query replaces four per-stage queries: it is equally
     * readable and preserves more of the transaction's SOQL governor limit.
     * USER_MODE enforces the caller's record access and object/field permissions.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null) {
            throw new IllegalArgumentException('Both dates are required.');
        }
        if (fromDate > toDate) {
            throw new IllegalArgumentException(
                'fromDate must be on or before toDate.'
            );
        }

        Map<String, Decimal> totals = new Map<String, Decimal>{
            'Prospecting' => 0,
            'Qualification' => 0,
            'Proposal/Price Quote' => 0,
            'Negotiation/Review' => 0
        };
        Set<String> stages = totals.keySet();

        List<AggregateResult> results = [
            SELECT StageName, SUM(Amount) stageTotal
            FROM Opportunity
            WHERE StageName IN :stages
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ];

        for (AggregateResult result : results) {
            Decimal stageTotal = (Decimal) result.get('stageTotal');
            totals.put(
                (String) result.get('StageName'),
                stageTotal == null ? 0 : stageTotal
            );
        }

        return totals;
    }
}
