public with sharing class ErpCustomerSync
    implements Queueable, Database.AllowsCallouts {

    private final List<Customer> customers;

    public ErpCustomerSync(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty() || accounts.size() > 200) {
            throw new IllegalArgumentException(
                'ErpCustomerSync requires between 1 and 200 accounts.'
            );
        }

        // Capture only the required fields from the inserted records.
        // This preserves their values without an additional database query.
        customers = new List<Customer>();
        for (Account accountRecord : accounts) {
            customers.add(new Customer(accountRecord));
        }
    }

    public void execute(QueueableContext context) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint('callout:ERP/api/customers');
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setTimeout(120000);

        // Explicitly retain null fields, including a blank BillingCountry.
        request.setBody(JSON.serialize(customers, false));

        // The ERP returns 202 Accepted. Error handling and retries are
        // intentionally outside this ticket's scope.
        new Http().send(request);
    }

    private class Customer {
        public String salesforceId;
        public String name;
        public String country;

        public Customer(Account accountRecord) {
            // Converting an Apex Id to String yields its 18-character form.
            salesforceId = String.valueOf(accountRecord.Id);
            name = accountRecord.Name;
            country = String.isBlank(accountRecord.BillingCountry)
                ? null
                : accountRecord.BillingCountry;
        }
    }
}
