```apex
/*
 * Deliberate differences from the requested per-opportunity call:
 * - Collect distinct Account IDs and schedule one job per trigger invocation.
 *   A transaction allows only 50 future calls, so 200 individual calls fail.
 * - Also handle reparenting, deletion and undeletion so ratings remain accurate.
 * - The service normally uses @future, with a Queueable fallback when future
 *   calls are unavailable. Both paths remain asynchronous.
 */
trigger OpportunityTrigger on Opportunity (
    after insert,
    after update,
    after delete,
    after undelete
) {
    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isDelete) {
        for (Opportunity opportunity : Trigger.old) {
            accountIds.add(opportunity.AccountId);
        }
    } else {
        for (Opportunity opportunity : Trigger.new) {
            if (Trigger.isInsert || Trigger.isUndelete) {
                accountIds.add(opportunity.AccountId);
                continue;
            }

            Opportunity previous = Trigger.oldMap.get(opportunity.Id);

            if (
                opportunity.StageName != previous.StageName ||
                opportunity.Amount != previous.Amount ||
                opportunity.AccountId != previous.AccountId
            ) {
                accountIds.add(opportunity.AccountId);
                accountIds.add(previous.AccountId);
            }
        }
    }

    accountIds.remove(null);

    if (!accountIds.isEmpty()) {
        AccountRatingService.scheduleRecalculation(accountIds);
    }
}
