/*
 * This is system-maintained derived data. Deliberately run without sharing
 * and in system mode: the saving user's record visibility and field permissions
 * must not produce a rating based on only part of an account's pipeline.
 */
public without sharing class AccountRatingService {
    private static final Decimal HOT_AMOUNT = 100000;

    public class AsyncCapacityException extends Exception {
    }

    public static void scheduleRecalculation(Set<Id> accountIds) {
        Set<Id> ids = cleanIds(accountIds);
        if (ids.isEmpty()) {
            return;
        }

        Boolean canUseFuture =
            !System.isFuture() &&
            !System.isBatch() &&
            !System.isQueueable() &&
            Limits.getFutureCalls() < Limits.getLimitFutureCalls();

        if (canUseFuture) {
            recalculate(ids);
            return;
        }

        // Future calls cannot be made from future or batch execution.
        // Queueable execution uses chaining rather than starting a future job.
        if (Limits.getQueueableJobs() < Limits.getLimitQueueableJobs()) {
            System.enqueueJob(new RecalculationJob(ids));
            return;
        }

        // Do not silently save an opportunity without scheduling its rating.
        throw new AsyncCapacityException(
            'No asynchronous capacity remains to recalculate account ratings.'
        );
    }

    @future
    public static void recalculate(Set<Id> accountIds) {
        updateRatings(accountIds);
    }

    private static Set<Id> cleanIds(Set<Id> accountIds) {
        Set<Id> ids = new Set<Id>();
        if (accountIds != null) {
            ids.addAll(accountIds);
            ids.remove(null);
        }
        return ids;
    }

    private static void updateRatings(Set<Id> accountIds) {
        Set<Id> ids = cleanIds(accountIds);
        if (ids.isEmpty()) {
            return;
        }

        /*
         * Lock accounts before reading their pipeline. Overlapping jobs for
         * the same account serialize their calculations instead of overwriting
         * a newer rating with an older calculation.
         */
        List<Account> accounts = [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :ids
            FOR UPDATE
        ];

        if (accounts.isEmpty()) {
            return;
        }

        Set<Id> existingAccountIds = new Set<Id>();
        for (Account account : accounts) {
            existingAccountIds.add(account.Id);
        }

        /*
         * Semi-joins test existence without loading every opportunity or
         * materializing large aggregate input sets.
         */
        Set<Id> accountsWithOpenOpportunities = new Set<Id>();
        for (Account account : [
            SELECT Id
            FROM Account
            WHERE Id IN :existingAccountIds
                AND Id IN (
                    SELECT AccountId
                    FROM Opportunity
                    WHERE IsClosed = false
                )
        ]) {
            accountsWithOpenOpportunities.add(account.Id);
        }

        Set<Id> hotAccountIds = new Set<Id>();
        for (Account account : [
            SELECT Id
            FROM Account
            WHERE Id IN :existingAccountIds
                AND Id IN (
                    SELECT AccountId
                    FROM Opportunity
                    WHERE IsClosed = false
                        AND Amount >= :HOT_AMOUNT
                )
        ]) {
            hotAccountIds.add(account.Id);
        }

        List<Account> changes = new List<Account>();

        for (Account account : accounts) {
            String desiredRating = 'Cold';

            if (hotAccountIds.contains(account.Id)) {
                desiredRating = 'Hot';
            } else if (accountsWithOpenOpportunities.contains(account.Id)) {
                desiredRating = 'Warm';
            }

            if (account.Rating != desiredRating) {
                changes.add(new Account(
                    Id = account.Id,
                    Rating = desiredRating
                ));
            }
        }

        // Avoid unnecessary DML and downstream automation.
        if (!changes.isEmpty()) {
            update changes;
        }
    }

    private without sharing class RecalculationJob implements Queueable {
        private Set<Id> accountIds;

        private RecalculationJob(Set<Id> accountIds) {
            this.accountIds = new Set<Id>(accountIds);
        }

        public void execute(QueueableContext context) {
            AccountRatingService.updateRatings(accountIds);
        }
    }
}
