public with sharing class LineItemDiscountHandler {
    /*
     * Change from the requested per-line call:
     * PricingRules.standardDiscountFor(productId) executes one SOQL query.
     * Calling it for 200 lines would exceed the synchronous 100-query limit.
     *
     * Instead, fetch the families in one query and call PricingRules'
     * existing, query-free standardDiscountForFamily method. PricingRules
     * remains unchanged, and no discount rules are duplicated here.
     *
     * Use PricebookEntryId to resolve each product because Product2Id may
     * not yet be populated on an OpportunityLineItem in before insert.
     */
    public static void applyStandardDiscounts(
        List<OpportunityLineItem> lines
    ) {
        Set<Id> pricebookEntryIds = new Set<Id>();

        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.PricebookEntryId != null) {
                pricebookEntryIds.add(line.PricebookEntryId);
            }
        }

        Map<Id, PricebookEntry> entriesById =
            new Map<Id, PricebookEntry>();

        if (!pricebookEntryIds.isEmpty()) {
            entriesById = new Map<Id, PricebookEntry>([
                SELECT Id, Product2.Family
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIds
            ]);
        }

        for (OpportunityLineItem line : lines) {
            // Preserve every explicitly supplied value, including zero.
            if (line.Discount != null) {
                continue;
            }

            PricebookEntry entry = entriesById.get(line.PricebookEntryId);

            if (entry == null || entry.Product2 == null) {
                line.addError(
                    'A valid, accessible price book entry is required '
                    + 'to determine the standard discount.'
                );
                continue;
            }

            line.Discount = PricingRules.standardDiscountForFamily(
                entry.Product2.Family
            );
        }
    }
}
