/**
 * Synchronizes eligible Contacts when an Account's BillingCountry changes.
 *
 * Why the query differs from the proposed approach:
 * Querying all 2.3 million Contacts would exceed the synchronous SOQL limit
 * of 50,000 rows and potentially the heap limit. Putting those records into
 * a map does not make that approach bulk-safe.
 *
 * Instead, identify changed Accounts first, then issue one query scoped to
 * those Accounts. No query is needed when no BillingCountry changed.
 *
 * This is synchronous automation: affected Contacts must still fit within
 * the transaction's remaining query-row and DML-row limits. Exceptional
 * high-fan-out Accounts require a separately designed Batch Apex solution,
 * not an unbounded query or a LIMIT that silently skips Contacts.
 *
 * Deliberately runs without sharing: this trigger maintains data integrity
 * for all related Contacts, not only those visible to the updating user.
 * It is not a user-facing access endpoint.
 */
public without sharing class AccountCountrySync {
    public static void afterUpdate(
        List<Account> newAccounts,
        Map<Id, Account> oldAccounts
    ) {
        Map<Id, Account> changedAccounts = new Map<Id, Account>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccounts.get(newAccount.Id);

            if (!countriesEqual(
                newAccount.BillingCountry,
                oldAccount.BillingCountry
            )) {
                changedAccounts.put(newAccount.Id, newAccount);
            }
        }

        if (changedAccounts.isEmpty()) {
            return;
        }

        Set<Id> changedAccountIds = changedAccounts.keySet();

        // One selective-by-parent query; no queries inside processing loops.
        List<Contact> relatedContacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact relatedContact : relatedContacts) {
            String previousCountry =
                oldAccounts.get(relatedContact.AccountId).BillingCountry;
            String newCountry =
                changedAccounts.get(relatedContact.AccountId).BillingCountry;

            Boolean shouldFollowAccount =
                String.isBlank(relatedContact.MailingCountry) ||
                countriesEqual(
                    relatedContact.MailingCountry,
                    previousCountry
                );

            if (
                shouldFollowAccount &&
                !countriesEqual(relatedContact.MailingCountry, newCountry)
            ) {
                // Sparse updates modify only the requested field.
                contactsToUpdate.add(new Contact(
                    Id = relatedContact.Id,
                    MailingCountry = newCountry
                ));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // All-or-none: do not silently allow Account/Contact divergence.
            update contactsToUpdate;
        }
    }

    /**
     * Null-safe, case-sensitive comparison so casing-only changes are
     * detected and propagated as well.
     */
    private static Boolean countriesEqual(String first, String second) {
        if (first == null) {
            return second == null;
        }

        return first.equals(second);
    }
}
