import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const CASE_LIST_PAGE_REFERENCE = {
    type: 'standard__objectPage',
    attributes: {
        objectApiName: 'Case',
        actionName: 'list'
    },
    state: {
        filterName: 'My_Open_Cases'
    }
};

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId;

    casesUrl;

    get recordActionsDisabled() {
        return !this.recordId;
    }

    connectedCallback() {
        this[NavigationMixin.GenerateUrl](CASE_LIST_PAGE_REFERENCE)
            .then((url) => {
                this.casesUrl = url;
            })
            .catch(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Navigation unavailable',
                        message: 'Unable to load the My open cases link.',
                        variant: 'error'
                    })
                );
            });
    }

    handleAction(event) {
        if (!this.recordId) {
            return;
        }

        let pageReference;

        switch (event.currentTarget.dataset.action) {
            case 'new-contact':
                pageReference = {
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Contact',
                        actionName: 'new'
                    },
                    state: {
                        defaultFieldValues: encodeDefaultFieldValues({
                            AccountId: this.recordId
                        })
                    }
                };
                break;

            case 'contacts':
                pageReference = {
                    type: 'standard__recordRelationshipPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        relationshipApiName: 'Contacts',
                        actionName: 'view'
                    }
                };
                break;

            case 'edit':
                pageReference = {
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        actionName: 'edit'
                    }
                };
                break;

            default:
                return;
        }

        this[NavigationMixin.Navigate](pageReference);
    }

    handleCasesClick(event) {
        // Preserve native modified-click behavior using the generated href.
        if (
            event.button !== 0 ||
            event.ctrlKey ||
            event.metaKey ||
            event.shiftKey ||
            event.altKey
        ) {
            return;
        }

        event.preventDefault();
        this[NavigationMixin.Navigate](CASE_LIST_PAGE_REFERENCE);
    }
}
