import { LightningElement, api, wire } from 'lwc';
import getContacts from '@salesforce/apex/ContactController.getContacts';
import { updateRecord } from 'lightning/uiRecordApi';
import { refreshApex } from '@salesforce/apex';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    columns = COLUMNS;
    draftValues = [];
    isSaving = false;

    @wire(getContacts, { accountId: '$recordId' })
    contacts;

    async handleSave(event) {
        this.draftValues = event.detail.draftValues;
        this.isSaving = true;

        try {
            // Wait for every update, including when some updates fail.
            const results = await Promise.allSettled(
                this.draftValues.map((draft) =>
                    updateRecord({ fields: { ...draft } })
                )
            );

            const failure = results.find(
                (result) => result.status === 'rejected'
            );

            if (failure) {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        message:
                            failure.reason?.body?.message ||
                            failure.reason?.message ||
                            'An unexpected error occurred.',
                        variant: 'error'
                    })
                );
                return;
            }

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Contacts updated',
                    variant: 'success'
                })
            );
            this.draftValues = [];

            try {
                await refreshApex(this.contacts);
            } catch (error) {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not refresh contacts',
                        message:
                            error?.body?.message ||
                            error?.message ||
                            'Contacts were saved, but the table could not be refreshed.',
                        variant: 'error'
                    })
                );
            }
        } finally {
            this.isSaving = false;
        }
    }
}
