import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = new Set([
    'ArrowDown',
    'ArrowUp',
    'Home',
    'End',
    'Enter',
    ' '
]);

export default class StatusListbox extends LightningElement {
    @api label = '';

    _options = [];
    _value;
    _activeIndex = -1;

    @api
    get options() {
        return this._options;
    }

    set options(options) {
        // Copy the input rather than mutating parent-owned data.
        this._options = Array.isArray(options)
            ? options.map((option) => ({
                  value: option.value,
                  label: option.label
              }))
            : [];

        this.syncActiveOption();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this.syncActiveOption();
    }

    get selectedIndex() {
        return this._options.findIndex(
            (option) => option.value === this._value
        );
    }

    get renderedOptions() {
        const selectedIndex = this.selectedIndex;

        return this._options.map((option, index) => ({
            id: this.optionId(index),
            index,
            value: option.value,
            label: option.label,
            ariaSelected: index === selectedIndex ? 'true' : 'false'
        }));
    }

    get activeOptionId() {
        if (
            this._activeIndex < 0 ||
            this._activeIndex >= this._options.length
        ) {
            return undefined;
        }

        // LWC scopes both this ID reference and the matching template ID.
        return this.optionId(this._activeIndex);
    }

    optionId(index) {
        return `status-option-${index}`;
    }

    syncActiveOption() {
        const selectedIndex = this.selectedIndex;

        if (selectedIndex !== -1) {
            this._activeIndex = selectedIndex;
        } else {
            this._activeIndex = this._options.length > 0 ? 0 : -1;
        }
    }

    handleKeyDown(event) {
        if (!HANDLED_KEYS.has(event.key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(
                    this._activeIndex + 1,
                    this._options.length - 1
                );
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);

        // Options never receive DOM focus.
        this.template.querySelector('[role="listbox"]').focus();
        this.selectOption(index);
    }

    selectOption(index) {
        if (
            !Number.isInteger(index) ||
            index < 0 ||
            index >= this._options.length
        ) {
            return;
        }

        this._activeIndex = index;
        const value = this._options[index].value;

        if (value === this._value) {
            return;
        }

        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value }
            })
        );
    }
}
