export default class TaskChecklist extends LightningElement {
    @api heading;

    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this.items;
    }

    set tasks(value) {
        this.items = Array.isArray(value)
            ? value.map((task) => ({ ...task }))
            : [];
    }

    get displayHeading() {
        return String(this.heading ?? '').toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.target.value;
    }

    handleAdd() {
        const label = (this.newLabel ?? '').trim();
        if (!label) {
            return;
        }

        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));

        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label }
            })
        );
    }

    handleToggle(event) {
        const id = event.currentTarget.dataset.id;
        const done = event.currentTarget.checked;

        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done } : task
        );
    }
}
