    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> stagedRows =
            new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            ImportResult result = new ImportResult();
            result.success = false;
            results.add(result);

            npsp__DataImport__c row = new npsp__DataImport__c(
                npsp__Status__c = 'Ready',
                npsp__Donation_Donor__c = 'Contact1'
            );

            // A null element still gets a staging row. NPSP determines
            // whether that row can be imported.
            if (gift != null) {
                row.npsp__Contact1_Firstname__c = gift.firstName;
                row.npsp__Contact1_Lastname__c = gift.lastName;
                row.npsp__Contact1_Personal_Email__c = gift.email;
                row.npsp__Donation_Amount__c = gift.amount;
                row.npsp__Donation_Date__c = gift.giftDate;
            }

            stagedRows.add(row);
        }

        // Respect the integration user's create permissions and allow
        // individual staging failures without rejecting the other rows.
        Database.SaveResult[] saveResults =
            Database.insert(stagedRows, false, AccessLevel.USER_MODE);

        List<npsp__DataImport__c> rowsToProcess =
            new List<npsp__DataImport__c>();
        Map<Id, ImportResult> resultsByImportId =
            new Map<Id, ImportResult>();

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (saveResults[i].isSuccess()) {
                rowsToProcess.add(stagedRows[i]);
                resultsByImportId.put(saveResults[i].getId(), results[i]);
            } else {
                // This row could not be staged, so there is no NPSP
                // processing result. Return the staging DML errors.
                results[i].errorMessage =
                    formatErrors(saveResults[i].getErrors());
            }
        }

        if (rowsToProcess.isEmpty()) {
            return results;
        }

        npsp__Data_Import_Settings__c settings =
            npsp__Data_Import_Settings__c.getOrgDefaults();

        // This API processes the entire collection synchronously.
        // Preserve the org's matching and donation-processing settings.
        // NPSP records ordinary row-level failures on the staging records;
        // unexpected transaction-level exceptions intentionally propagate.
        npsp.BDI_DataImport_API.processDataImportBatch(
            settings,
            rowsToProcess
        );

        Set<Id> importIds = resultsByImportId.keySet();

        // Read persisted results rather than assuming that the API updated
        // the caller's in-memory objects. Never delete these audit records.
        for (npsp__DataImport__c row : [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :importIds
            WITH USER_MODE
        ]) {
            ImportResult result = resultsByImportId.get(row.Id);
            result.success = row.npsp__Status__c == 'Imported';
            result.contactId = row.npsp__Contact1Imported__c;
            result.opportunityId = row.npsp__DonationImported__c;
            result.errorMessage = result.success
                ? null
                : row.npsp__FailureInformation__c;
        }

        // The list was allocated in input order; query order is irrelevant.
        return results;
    }

    private static String formatErrors(Database.Error[] errors) {
        List<String> messages = new List<String>();

        for (Database.Error error : errors) {
            messages.add(
                String.valueOf(error.getStatusCode()) + ': ' +
                error.getMessage()
            );
        }

        return String.join(messages, '\n');
    }
}
