public with sharing class HouseholdService {
    public class HouseholdCreationException extends Exception {}

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'At least one household member is required.'
            );
        }

        // Work on copies so a rollback does not leave invalid IDs or account
        // assignments on the caller's contacts.
        List<Contact> contactsToInsert = new List<Contact>();
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException(
                    'Household members cannot contain null entries.'
                );
            }
            if (member.Id != null || member.AccountId != null) {
                throw new IllegalArgumentException(
                    'Household members must be new contacts without AccountId.'
                );
            }
            contactsToInsert.add(member.clone(false, false, false, false));
        }

        Schema.RecordTypeInfo householdRecordType =
            Account.SObjectType.getDescribe()
                .getRecordTypeInfosByDeveloperName()
                .get('HH_Account');

        if (householdRecordType == null || !householdRecordType.isActive()) {
            throw new HouseholdCreationException(
                'The HH_Account record type must exist and be active.'
            );
        }

        Id householdRecordTypeId = householdRecordType.getRecordTypeId();
        Savepoint transactionStart = Database.setSavepoint();

        try {
            // Let NPSP create and name the household for this contact.
            // Inserting all members without AccountId would create extras.
            Contact firstMember = contactsToInsert[0];
            insert as user firstMember;

            // Requery: NPSP's AccountId assignment need not be reflected on
            // the original in-memory Contact.
            Contact persistedFirstMember = [
                SELECT AccountId
                FROM Contact
                WHERE Id = :firstMember.Id
                WITH USER_MODE
            ];

            Id householdId = persistedFirstMember.AccountId;
            if (householdId == null) {
                throw new HouseholdCreationException(
                    'NPSP did not create a household for the first member.'
                );
            }

            Account household = [
                SELECT Id, RecordTypeId
                FROM Account
                WHERE Id = :householdId
                WITH USER_MODE
            ];

            if (household.RecordTypeId != householdRecordTypeId) {
                throw new HouseholdCreationException(
                    'NPSP did not create an HH_Account household.'
                );
            }

            // Attach every remaining contact to the existing household before
            // insertion, allowing NPSP to update its name and greetings.
            List<Contact> remainingMembers = new List<Contact>();
            for (Integer i = 1; i < contactsToInsert.size(); i++) {
                contactsToInsert[i].AccountId = householdId;
                remainingMembers.add(contactsToInsert[i]);
            }

            if (!remainingMembers.isEmpty()) {
                insert as user remainingMembers;
            }

            // Explicitly establish the first member as primary after all
            // contact-insert automation has completed.
            Account primaryContactUpdate = new Account(
                Id = householdId,
                npe01__One2OneContact__c = firstMember.Id
            );
            update as user primaryContactUpdate;

            for (Integer i = 0; i < members.size(); i++) {
                members[i].Id = contactsToInsert[i].Id;
                members[i].AccountId = householdId;
            }

            return householdId;
        } catch (Exception failure) {
            // Remove the generated household and all inserted contacts even
            // if the caller catches the exception.
            Database.rollback(transactionStart);
            throw failure;
        } finally {
            Database.releaseSavepoint(transactionStart);
        }
    }
}
