public with sharing class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist or is inaccessible.');
        }

        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'The contact must belong to a household account.'
            );
        }

        Set<Id> householdContactIds = new Set<Id>{ donor.Id };
        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
            WITH USER_MODE
        ]) {
            householdContactIds.add(member.Id);
        }

        String donorName = String.isBlank(donor.FirstName)
            ? donor.LastName
            : donor.FirstName + ' ' + donor.LastName;

        Opportunity gift = new Opportunity(
            Name = donorName + ' Donation ' + String.valueOf(giftDate),
            AccountId = donor.AccountId,
            Amount = amount,
            StageName = 'Closed Won',
            CloseDate = giftDate,
            npsp__Primary_Contact__c = donor.Id
        );

        // Preserve the requested name when NPSP automatic naming is enabled.
        // Dynamic access avoids requiring this additional package field at compile time.
        if (Opportunity.SObjectType.getDescribe().fields.getMap()
                .containsKey('npsp__Naming_Exception__c')) {
            gift.put('npsp__Naming_Exception__c', true);
        }

        Savepoint sp = Database.setSavepoint();
        try {
            insert as user gift;

            // NPSP can create roles and payments during the Opportunity insert.
            // Reconcile those records instead of unconditionally creating more.
            reconcileContactRoles(gift.Id, donor.Id, householdContactIds);
            reconcilePayment(gift.Id, amount, giftDate);

            return gift.Id;
        } catch (Exception e) {
            // Do not leave a partial gift if the caller catches the exception.
            Database.rollback(sp);
            throw e;
        }
    }

    private static void reconcileContactRoles(
        Id opportunityId,
        Id donorId,
        Set<Id> householdContactIds
    ) {
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            WITH USER_MODE
            ORDER BY IsPrimary DESC, CreatedDate ASC, Id ASC
        ];

        Map<Id, OpportunityContactRole> roleByContact =
            new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> duplicates =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole role : existingRoles) {
            if (roleByContact.containsKey(role.ContactId)) {
                duplicates.add(role);
            } else {
                roleByContact.put(role.ContactId, role);
            }
        }

        List<OpportunityContactRole> rolesToUpdate =
            new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToInsert =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole role : roleByContact.values()) {
            Boolean desiredPrimary = role.ContactId == donorId;
            String desiredRole = role.Role;

            if (desiredPrimary) {
                desiredRole = 'Donor';
            } else if (householdContactIds.contains(role.ContactId)) {
                desiredRole = 'Household Member';
            }

            // Preserve unrelated NPSP relationship/soft-credit roles, but ensure
            // that only the donor is primary and each contact has only one role.
            if (role.IsPrimary != desiredPrimary || role.Role != desiredRole) {
                role.IsPrimary = desiredPrimary;
                role.Role = desiredRole;
                rolesToUpdate.add(role);
            }
        }

        if (!roleByContact.containsKey(donorId)) {
            rolesToInsert.add(new OpportunityContactRole(
                OpportunityId = opportunityId,
                ContactId = donorId,
                Role = 'Donor',
                IsPrimary = true
            ));
        }

        for (Id memberId : householdContactIds) {
            if (memberId != donorId && !roleByContact.containsKey(memberId)) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = memberId,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!duplicates.isEmpty()) {
            delete as user duplicates;
        }
        if (!rolesToUpdate.isEmpty()) {
            update as user rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert as user rolesToInsert;
        }
    }

    private static void reconcilePayment(
        Id opportunityId,
        Decimal amount,
        Date giftDate
    ) {
        // Query after role reconciliation to include any synchronous NPSP work.
        List<npe01__OppPayment__c> payments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c,
                   npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            ORDER BY npe01__Paid__c DESC, CreatedDate ASC, Id ASC
        ];

        if (payments.isEmpty()) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            insert as user payment;
            return;
        }

        // Retain one existing payment, preferring an already-paid payment.
        npe01__OppPayment__c keeper = payments.remove(0);

        if (!payments.isEmpty()) {
            delete as user payments;
        }

        if (keeper.npe01__Payment_Amount__c != amount ||
            keeper.npe01__Payment_Date__c != giftDate ||
            keeper.npe01__Scheduled_Date__c != giftDate ||
            keeper.npe01__Paid__c != true) {
            keeper.npe01__Payment_Amount__c = amount;
            keeper.npe01__Payment_Date__c = giftDate;
            keeper.npe01__Scheduled_Date__c = giftDate;
            keeper.npe01__Paid__c = true;
            update as user keeper;
        }
    }
}
