public with sharing class FamilyService {
    /**
     * Creates parent relationships and lets NPSP create their reciprocals.
     * Existing relationships, regardless of type or status, are left untouched.
     *
     * Null or empty input is a no-op. Invalid endpoints are rejected before DML.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null) {
                throw new IllegalArgumentException(
                    'Each pair must contain both a child Contact Id and a parent Contact Id.'
                );
            }
            if (childId.getSObjectType() != Contact.SObjectType ||
                parentId.getSObjectType() != Contact.SObjectType) {
                throw new IllegalArgumentException(
                    'Both endpoints must be Contact Ids.'
                );
            }
            if (childId == parentId) {
                throw new IllegalArgumentException(
                    'A Contact cannot be their own parent.'
                );
            }

            childIds.add(childId);
            parentIds.add(parentId);
        }

        Set<String> seenPairs =
            new ExistingRelationshipReader().findPairs(childIds, parentIds);

        List<npe4__Relationship__c> relationshipsToInsert =
            new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            String key = pairKey(childId, parentId);

            if (seenPairs.contains(key)) {
                continue;
            }

            // Type describes Contact's role relative to Related Contact.
            // The parent is the child's Parent, so the parent is Contact.
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));

            // Also prevents duplicate unordered pairs within this invocation.
            seenPairs.add(key);
        }

        if (!relationshipsToInsert.isEmpty()) {
            // Enforce caller CRUD, FLS and record access; insertion is atomic.
            // NPSP creates and links the reciprocal using its List Setting
            // lookup and the child's gender. Do not insert it ourselves.
            insert as user relationshipsToInsert;
        }
    }

    private static String pairKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        return first.compareTo(second) < 0
            ? first + ':' + second
            : second + ':' + first;
    }

    /**
     * Duplicate detection must include relationships hidden by sharing.
     * This narrowly scoped system-context reader returns only pair keys
     * internally; creation still runs in user mode.
     */
    private without sharing class ExistingRelationshipReader {
        public Set<String> findPairs(
            Set<Id> childIds,
            Set<Id> parentIds
        ) {
            Set<String> pairs = new Set<String>();

            for (npe4__Relationship__c relationship : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM npe4__Relationship__c
                WHERE (
                    npe4__Contact__c IN :parentIds
                    AND npe4__RelatedContact__c IN :childIds
                ) OR (
                    npe4__Contact__c IN :childIds
                    AND npe4__RelatedContact__c IN :parentIds
                )
            ]) {
                pairs.add(FamilyService.pairKey(
                    relationship.npe4__Contact__c,
                    relationship.npe4__RelatedContact__c
                ));
            }

            return pairs;
        }
    }
}
