global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper result =
            new npsp.TDTM_Runnable.DmlWrapper();

        if (
            triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate
        ) {
            return result;
        }

        if (newlist == null || newlist.isEmpty()) {
            return result;
        }

        Map<Id, Opportunity> oldOpportunities = new Map<Id, Opportunity>();
        if (
            triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate &&
            oldlist != null
        ) {
            for (SObject oldRecord : oldlist) {
                Opportunity oldOpportunity = (Opportunity) oldRecord;
                oldOpportunities.put(oldOpportunity.Id, oldOpportunity);
            }
        }

        for (SObject newRecord : newlist) {
            Opportunity opportunity = (Opportunity) newRecord;

            if (!qualifies(opportunity)) {
                continue;
            }

            if (
                triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate &&
                qualifies(oldOpportunities.get(opportunity.Id))
            ) {
                continue;
            }

            // Queue the Task for TDTM's bulk DML rather than performing DML here.
            result.objectsToInsert.add(new Task(
                Subject = 'Major gift thank-you call',
                Priority = 'High',
                Status = 'Not Started',
                WhatId = opportunity.Id,
                WhoId = opportunity.npsp__Primary_Contact__c,
                OwnerId = opportunity.OwnerId,
                ActivityDate = opportunity.CloseDate.addDays(3)
            ));
        }

        return result;
    }

    private static Boolean qualifies(Opportunity opportunity) {
        return opportunity != null &&
            opportunity.StageName == 'Closed Won' &&
            opportunity.Amount != null &&
            opportunity.Amount >= 5000;
    }
}
