public with sharing class RecordAccessService {
    // UserRecordAccess supports at most 200 RecordIds per query.
    private static final Integer QUERY_BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        Id runningUserId = UserInfo.getUserId();
        List<Id> batch = new List<Id>();

        // Batch across object types, using at most 10 queries for 2,000 IDs.
        for (Id recordId : recordIds) {
            if (recordId == null) {
                continue;
            }

            batch.add(recordId);
            if (batch.size() == QUERY_BATCH_SIZE) {
                collectEditableIds(runningUserId, batch, editable);
                batch.clear();
            }
        }

        if (!batch.isEmpty()) {
            collectEditableIds(runningUserId, batch, editable);
        }

        return editable;
    }

    private static void collectEditableIds(
        Id userId,
        List<Id> recordIds,
        Set<Id> editable
    ) {
        for (UserRecordAccess access : [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :userId
                AND RecordId IN :recordIds
        ]) {
            if (access.HasEditAccess == true) {
                editable.add(access.RecordId);
            }
        }
    }
}
