public with sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                OwnerId = newOwnerId
            ));
        }

        // Query before transferring Accounts, which can change record access.
        List<Contact> contactsToUpdate = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
            WITH USER_MODE
        ];
        for (Contact contactRecord : contactsToUpdate) {
            contactRecord.OwnerId = newOwnerId;
        }

        TriggerBase.bypass(Account.SObjectType);
        try {
            // Standard DML is all-or-none. User mode enforces access permissions.
            update as user accountsToUpdate;

            if (!contactsToUpdate.isEmpty()) {
                // No Contact bypass: its registered actions execute normally.
                update as user contactsToUpdate;
            }
        } finally {
            // Clear only our Account bypass, including when DML throws.
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
