        );

        assertNoErrors(newRecord, 'Reduction from 1000 to 500');
    }

    @IsTest
    static void increaseIsAccepted() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = new Opportunity(
            Id = opportunityId,
            Amount = 1000
        );
        Opportunity newRecord = new Opportunity(
            Id = opportunityId,
            Amount = 1500
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newRecord },
            new List<Opportunity>{ oldRecord }
        );

        assertNoErrors(newRecord, 'Increase from 1000 to 1500');
    }

    @IsTest
    static void nullPreviousAmountIsAccepted() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = new Opportunity(
            Id = opportunityId,
            Amount = null
        );
        Opportunity newRecord = new Opportunity(
            Id = opportunityId,
            Amount = 250
        );

        // Any exception from handling the null previous Amount fails this test.
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newRecord },
            new List<Opportunity>{ oldRecord }
        );

        assertNoErrors(newRecord, 'Previous Amount is null');
    }

    @IsTest
    static void mixedRecordsReceiveOnlyTheirOwnErrors() {
        List<Decimal> previousAmounts = new List<Decimal>{
            1000, 1000, 1000, null, 1000, 1000, 800
        };
        List<Decimal> currentAmounts = new List<Decimal>{
            499, 500, 1250, 250, null, 1000, 399
        };
        List<Boolean> expectedErrors = new List<Boolean>{
            true, false, false, false, false, false, true
        };

        List<Opportunity> triggerNew = new List<Opportunity>();
        List<Opportunity> triggerOld = new List<Opportunity>();

        for (Integer i = 0; i < previousAmounts.size(); i++) {
            Id opportunityId =
                TriggerTestUtility.getFakeId(Opportunity.SObjectType);

            triggerNew.add(new Opportunity(
                Id = opportunityId,
                Amount = currentAmounts[i]
            ));
            triggerOld.add(new Opportunity(
                Id = opportunityId,
                Amount = previousAmounts[i]
            ));
        }

        // Deliberately change the old-list ordering to verify matching by Id.
        Opportunity firstOldRecord = triggerOld.remove(0);
        triggerOld.add(firstOldRecord);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            triggerNew,
            triggerOld
        );

        Integer rejectedCount = 0;
        for (Integer i = 0; i < triggerNew.size(); i++) {
            String context = 'Mixed record at index ' + i;
            if (expectedErrors[i]) {
                assertRuleError(triggerNew[i], context);
            } else {
                assertNoErrors(triggerNew[i], context);
            }

            if (triggerNew[i].hasErrors()) {
                rejectedCount++;
            }
        }

        Assert.areEqual(
            2,
            rejectedCount,
            'Exactly the two excessive reductions must be rejected'
        );

        for (Opportunity oldRecord : triggerOld) {
            assertNoErrors(oldRecord, 'Old record ' + oldRecord.Id);
        }
    }

    private static void assertRuleError(
        Opportunity record,
        String context
    ) {
        Assert.isTrue(record.hasErrors(), context + ': expected an error');

        List<Database.Error> errors = record.getErrors();
        Assert.areEqual(
            1,
            errors.size(),
            context + ': expected exactly one error'
        );
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            context + ': incorrect error message'
        );
    }

    private static void assertNoErrors(
        Opportunity record,
        String context
    ) {
        Assert.isFalse(record.hasErrors(), context + ': unexpected error');
        Assert.areEqual(
            0,
            record.getErrors().size(),
            context + ': expected an empty error list'
        );
    }
}
